function resolveDriveIntent(rawThrottle, rawBrake) {
  const forward = rawThrottle > 0.05;
  const reverse = rawBrake > 0.05;
  if (forward && !reverse) return 1;
  if (reverse && !forward) return -1;
  if (forward && reverse) {
    if (rawThrottle > rawBrake + 0.05) return 1;
    if (rawBrake > rawThrottle + 0.05) return -1;
  }
  return 0;
}

function currentTransmissionOutput({ throttle, brake, handbrake, longSpeed = 20 }) {
  const driveIntent = resolveDriveIntent(throttle, brake);
  const wantsForward = driveIntent > 0;
  const wantsReverse = driveIntent < 0;
  let driveThrottle = 0;
  let serviceBrake = 0;

  if (wantsForward) {
    if (longSpeed < -0.22) serviceBrake = throttle;
    else driveThrottle = throttle;
  } else if (wantsReverse) {
    if (longSpeed > 0.22) serviceBrake = brake;
  }

  return { driveIntent, driveThrottle, serviceBrake, handbrake };
}

function nominalBrakeTorques(brakeTorque, serviceBrake, handbrake) {
  return {
    frontLeft: serviceBrake * brakeTorque * 0.31,
    frontRight: serviceBrake * brakeTorque * 0.31,
    rearLeft: serviceBrake * brakeTorque * 0.19 + handbrake * brakeTorque * 0.62,
    rearRight: serviceBrake * brakeTorque * 0.19 + handbrake * brakeTorque * 0.62
  };
}

const cases = [
  { name: 'S only', throttle: 0, brake: 1, handbrake: 0 },
  { name: 'W plus S', throttle: 1, brake: 1, handbrake: 0 },
  { name: 'W plus Space', throttle: 1, brake: 0, handbrake: 1 }
];

for (const input of cases) {
  const output = currentTransmissionOutput(input);
  const torques = nominalBrakeTorques(2450, output.serviceBrake, output.handbrake);
  console.log(JSON.stringify({ input, output, mx5NominalBrakeTorques: torques }, null, 2));
}
